  1	//! The WebM writer (spec §11 CX-6, CX-15): one file of AV1 video and Opus
  2	//! sound, written from compressed packets the app hands in as opaque bytes.
  3	//! Nothing here encodes or decodes; it decides the container — the header,
  4	//! the timestamps, the interleave, the Clusters and the Cues.
  5	//!
  6	//! **The layout** (CX-15 (3)) is fixed at `open` from a [`WebmLayout`]
  7	//! (`webm_layout.rs`, which checks it and builds its elements): the
  8	//! EBML header (DocType `webm` 4/2), a Segment whose size is patched at
  9	//! `finish`, a Void reserved for the SeekHead `finish` writes over it, Info,
 10	//! Tracks and, when there are any, Chapters. Clusters follow as packets
 11	//! arrive, and Cues close the file. Element bytes are `webm_ebml.rs`'s.
 12	//!
 13	//! **The interleave** (CX-15 (4)): each declared track has a queue, and the
 14	//! earliest head (by its millisecond time, video first among equal times) is
 15	//! written only while every declared track that has not ended has a head,
 16	//! so the file's blocks are in nondecreasing time whatever order two pumps
 17	//! deliver them in. `end_track` releases a track's claim; a layout with one
 18	//! track writes each packet as it arrives. Each call ends with a flush, so
 19	//! what was written is on disk when it returns.
 20	//!
 21	//! **Clusters** start before each video key block, and before a block whose
 22	//! time would pass the 16-bit relative limit (32,767 ms); a Cluster's size is
 23	//! written unknown and patched when the next one starts. Each key-started
 24	//! Cluster is a CuePoint.
 25	
 26	use std::collections::VecDeque;
 27	use std::fs::File;
 28	use std::io::{BufWriter, Seek, SeekFrom, Write};
 29	use std::path::Path;
 30	
 31	use crate::webm_ebml as ebml;
 32	pub use crate::webm_layout::WebmLayout;
 33	
 34	/// The track number of the video track, and `add_packet`'s argument for it.
 35	pub const VIDEO: u32 = 1;
 36	/// The track number of the audio track.
 37	pub const AUDIO: u32 = 2;
 38	
 39	/// The bytes reserved after the Segment's header for the SeekHead: four
 40	/// entries take 89 (`ebml::seek_head`), and the rest stays a Void.
 41	const SEEK_RESERVE: usize = 96;
 42	/// The largest time a block may sit after its Cluster's, in ms.
 43	const MAX_RELATIVE_MS: u64 = 32_767;
 44	
 45	struct Packet {
 46	    ms: u64,
 47	    key: bool,
 48	    discard_ns: i64,
 49	    bytes: Vec<u8>,
 50	}
 51	
 52	#[derive(Default)]
 53	struct Track {
 54	    queue: VecDeque<Packet>,
 55	    last_ns: Option<i64>,
 56	    ended: bool,
 57	}
 58	
 59	/// The open Cluster: where its size is to be patched, and its time.
 60	struct Cluster {
 61	    size_at: u64,
 62	    ms: u64,
 63	}
 64	
 65	/// One WebM file being written.
 66	pub struct WebmWriter {
 67	    file: Option<BufWriter<File>>,
 68	    pos: u64,
 69	    segment_data: u64,
 70	    level_one: Vec<(u32, u64)>,
 71	    tracks: [Option<Track>; 2],
 72	    cluster: Option<Cluster>,
 73	    cues: Vec<(u64, u64)>,
 74	    failed: bool,
 75	}
 76	
 77	impl WebmWriter {
 78	    /// Checks `layout` (JSON), creates the file at `path` and writes
 79	    /// everything up to the first Cluster.
 80	    pub fn open(path: &Path, layout: &str) -> Result<WebmWriter, String> {
 81	        let head = WebmLayout::header(layout)?;
 82	        let file =
 83	            File::create(path).map_err(|e| format!("the file could not be created ({e})"))?;
 84	        let mut w = WebmWriter {
 85	            file: Some(BufWriter::new(file)),
 86	            pos: 0,
 87	            segment_data: 0,
 88	            level_one: Vec::new(),
 89	            tracks: [
 90	                head.video.then(Track::default),
 91	                head.audio.then(Track::default),
 92	            ],
 93	            cluster: None,
 94	            cues: Vec::new(),
 95	            failed: false,
 96	        };
 97	        w.put(&ebml::ebml_header())?;
 98	        w.put(&ebml::id(ebml::SEGMENT))?;
 99	        w.put(&ebml::UNKNOWN_SIZE)?;
100	        w.segment_data = w.pos;
101	        w.put(&ebml::void(SEEK_RESERVE))?;
102	        let level_one = [
103	            Some((ebml::INFO, head.info)),
104	            Some((ebml::TRACKS, head.tracks)),
105	            head.chapters.map(|bytes| (ebml::CHAPTERS, bytes)),
106	        ];
107	        for (id, bytes) in level_one.into_iter().flatten() {
108	            w.level_one.push((id, w.pos - w.segment_data));
109	            w.put(&bytes)?;
110	        }
111	        w.flush()?;
112	        Ok(w)
113	    }
114	
115	    /// Queues one packet of `track` and writes whatever the interleave
116	    /// allows. `pts_ns` must be at or after 0 and after the track's last.
117	    pub fn add_packet(
118	        &mut self,
119	        track: u32,
120	        pts_ns: i64,
121	        key: bool,
122	        discard_padding_ns: i64,
123	        bytes: &[u8],
124	    ) -> Result<(), String> {
125	        let t = self.track(track)?;
126	        if pts_ns < 0 {
127	            return Err(format!("pts {pts_ns} ns on track {track} is negative"));
128	        }
129	        if let Some(last) = t.last_ns.filter(|last| pts_ns <= *last) {
130	            return Err(format!(
131	                "pts {pts_ns} ns on track {track} is not after its last, {last} ns"
132	            ));
133	        }
134	        t.last_ns = Some(pts_ns);
135	        // round-half-up(pts_ns / 1e6) ms.
136	        let ms = (pts_ns as u64).saturating_add(500_000) / 1_000_000;
137	        t.queue.push_back(Packet {
138	            ms,
139	            key,
140	            discard_ns: discard_padding_ns,
141	            bytes: bytes.to_vec(),
142	        });
143	        self.drain(false)?;
144	        self.flush()
145	    }
146	
147	    /// Ends `track`: no packet follows, and the others no longer wait for it.
148	    pub fn end_track(&mut self, track: u32) -> Result<(), String> {
149	        self.track(track)?.ended = true;
150	        self.drain(false)?;
151	        self.flush()
152	    }
153	
154	    /// Writes every queued packet, the Cues, the SeekHead and the Segment's
155	    /// size, and closes the file. Nothing may be added after it.
156	    pub fn finish(&mut self) -> Result<(), String> {
157	        self.check_open()?;
158	        for t in self.tracks.iter_mut().flatten() {
159	            t.ended = true;
160	        }
161	        self.drain(true)?;
162	        self.close_cluster()?;
163	        let mut seeks = self.level_one.clone();
164	        if !self.cues.is_empty() {
165	            seeks.push((ebml::CUES, self.pos - self.segment_data));
166	            let cues = ebml::cues(&self.cues);
167	            self.put(&cues)?;
168	        }
169	        let mut head = ebml::seek_head(&seeks);
170	        head.extend(ebml::void(SEEK_RESERVE - head.len()));
171	        self.patch(self.segment_data, &head)?;
172	        let size = ebml::size8(self.pos - self.segment_data);
173	        self.patch(self.segment_data - 8, &size)?;
174	        self.flush()?;
175	        self.file = None;
176	        Ok(())
177	    }
178	
179	    // ---- the interleave -----------------------------------------------------
180	
181	    fn check_open(&self) -> Result<(), String> {
182	        if self.file.is_none() {
183	            return Err("the file is finished".to_string());
184	        }
185	        if self.failed {
186	            return Err("the file could not be written earlier".to_string());
187	        }
188	        Ok(())
189	    }
190	
191	    /// The open track `number`, or the sentence refusing it.
192	    fn track(&mut self, number: u32) -> Result<&mut Track, String> {
193	        self.check_open()?;
194	        let slot = match number {
195	            VIDEO => self.tracks[0].as_mut(),
196	            AUDIO => self.tracks[1].as_mut(),
197	            _ => None,
198	        };
199	        let t = slot.ok_or_else(|| format!("track {number} is not in the layout"))?;
200	        if t.ended {
201	            return Err(format!("track {number} has ended"));
202	        }
203	        Ok(t)
204	    }
205	
206	    /// Writes heads while the interleave allows; `all` writes every one.
207	    fn drain(&mut self, all: bool) -> Result<(), String> {
208	        loop {
209	            let waiting = self
210	                .tracks
211	                .iter()
212	                .flatten()
213	                .any(|t| !t.ended && t.queue.is_empty());
214	            if waiting && !all {
215	                return Ok(());
216	            }
217	            let next = (0..2)
218	                .filter_map(|i| {
219	                    let head = self.tracks[i].as_ref()?.queue.front()?;
220	                    Some((head.ms, i))
221	                })
222	                .min();
223	            let Some((_, i)) = next else {
224	                return Ok(());
225	            };
226	            let Some(packet) = self.tracks[i].as_mut().and_then(|t| t.queue.pop_front()) else {
227	                return Ok(());
228	            };
229	            self.write_block(i as u32 + 1, &packet)?;
230	        }
231	    }
232	
233	    fn write_block(&mut self, track: u32, p: &Packet) -> Result<(), String> {
234	        let video_key = track == VIDEO && p.key;
235	        let fresh = match &self.cluster {
236	            None => true,
237	            Some(c) => video_key || p.ms.saturating_sub(c.ms) > MAX_RELATIVE_MS,
238	        };
239	        if fresh {
240	            self.close_cluster()?;
241	            if video_key {
242	                self.cues.push((p.ms, self.pos - self.segment_data));
243	            }
244	            self.put(&ebml::id(ebml::CLUSTER))?;
245	            let size_at = self.pos;
246	            self.put(&ebml::UNKNOWN_SIZE)?;
247	            self.put(&ebml::uint(ebml::TIMESTAMP, p.ms))?;
248	            self.cluster = Some(Cluster { size_at, ms: p.ms });
249	        }
250	        let base = self.cluster.as_ref().map_or(p.ms, |c| c.ms);
251	        let relative = i16::try_from(p.ms.saturating_sub(base)).unwrap_or(i16::MAX);
252	        let element = if p.discard_ns > 0 {
253	            ebml::block_group(
254	                &ebml::block_body(track, relative, 0, &p.bytes),
255	                p.discard_ns,
256	            )
257	        } else {
258	            let flags = if track == AUDIO || p.key { 0x80 } else { 0 };
259	            ebml::binary(
260	                ebml::SIMPLE_BLOCK,
261	                &ebml::block_body(track, relative, flags, &p.bytes),
262	            )
263	        };
264	        self.put(&element)
265	    }
266	
267	    fn close_cluster(&mut self) -> Result<(), String> {
268	        if let Some(c) = self.cluster.take() {
269	            let size = ebml::size8(self.pos - c.size_at - 8);
270	            self.patch(c.size_at, &size)?;
271	        }
272	        Ok(())
273	    }
274	
275	    // ---- the file -----------------------------------------------------------
276	
277	    fn io<T>(&mut self, result: std::io::Result<T>) -> Result<T, String> {
278	        result.map_err(|e| {
279	            self.failed = true;
280	            format!("the file could not be written ({e})")
281	        })
282	    }
283	
284	    fn put(&mut self, bytes: &[u8]) -> Result<(), String> {
285	        let Some(file) = self.file.as_mut() else {
286	            return Err("the file is finished".to_string());
287	        };
288	        let written = file.write_all(bytes);
289	        self.io(written)?;
290	        self.pos += bytes.len() as u64;
291	        Ok(())
292	    }
293	
294	    /// Overwrites `bytes` at `at`, then returns to the end.
295	    fn patch(&mut self, at: u64, bytes: &[u8]) -> Result<(), String> {
296	        let end = self.pos;
297	        let Some(file) = self.file.as_mut() else {
298	            return Err("the file is finished".to_string());
299	        };
300	        let done = file
301	            .seek(SeekFrom::Start(at))
302	            .and_then(|_| file.write_all(bytes))
303	            .and_then(|_| file.seek(SeekFrom::Start(end)));
304	        self.io(done).map(|_| ())
305	    }
306	
307	    fn flush(&mut self) -> Result<(), String> {
308	        let Some(file) = self.file.as_mut() else {
309	            return Ok(());
310	        };
311	        let flushed = file.flush();
312	        self.io(flushed)
313	    }
314	}
  1	//! The WebM writer's layout (spec §11 CX-15 (3)): `rc_webm_open`'s JSON as
  2	//! [`WebmLayout`], every value checked in a lowercase sentence naming it, and
  3	//! the level-1 elements `webm_writer.rs` writes before the first Cluster —
  4	//! Info, Tracks and Chapters — built through `webm_ebml.rs`. Split out of
  5	//! `webm_writer.rs` so each stays under the 400-line cap for a new module.
  6	
  7	use serde::Deserialize;
  8	
  9	use crate::container_codec::{light_from_clli, mastering_from_mdcv};
 10	use crate::webm_ebml::{self as ebml, ColourOut};
 11	
 12	/// The file's shape, as `rc_webm_open`'s JSON.
 13	#[derive(Deserialize)]
 14	#[serde(deny_unknown_fields)]
 15	pub struct WebmLayout {
 16	    pub duration_ns: u64,
 17	    pub video: Option<VideoLayout>,
 18	    pub audio: Option<AudioLayout>,
 19	    #[serde(default)]
 20	    pub chapters: Vec<ChapterLayout>,
 21	}
 22	
 23	#[derive(Deserialize)]
 24	#[serde(deny_unknown_fields)]
 25	pub struct VideoLayout {
 26	    pub codec_id: String,
 27	    /// The `av1C` record on `V_AV1`; absent on `V_VP9`, whose mapping
 28	    /// makes CodecPrivate optional (spec §11 CX-16 (5)).
 29	    #[serde(default)]
 30	    pub codec_private_hex: Option<String>,
 31	    pub width: u32,
 32	    pub height: u32,
 33	    pub fps: [u32; 2],
 34	    pub colour: ColourLayout,
 35	}
 36	
 37	#[derive(Deserialize)]
 38	#[serde(deny_unknown_fields)]
 39	pub struct ColourLayout {
 40	    pub matrix: u8,
 41	    pub range: u8,
 42	    pub transfer: u8,
 43	    pub primaries: u8,
 44	    pub bits_per_channel: u8,
 45	    pub mdcv_hex: Option<String>,
 46	    pub clli_hex: Option<String>,
 47	}
 48	
 49	#[derive(Deserialize)]
 50	#[serde(deny_unknown_fields)]
 51	pub struct AudioLayout {
 52	    pub codec_id: String,
 53	    pub channels: u8,
 54	    pub sample_rate: u32,
 55	    pub pre_skip: u16,
 56	}
 57	
 58	#[derive(Deserialize)]
 59	#[serde(deny_unknown_fields)]
 60	pub struct ChapterLayout {
 61	    pub start_ns: u64,
 62	    pub end_ns: u64,
 63	    pub name: String,
 64	}
 65	
 66	/// Lowercase or uppercase hex as bytes, naming `field` when it is not hex.
 67	fn unhex(field: &str, text: &str) -> Result<Vec<u8>, String> {
 68	    let bad = || format!("{field} \"{text}\" is not hex");
 69	    if !text.len().is_multiple_of(2) {
 70	        return Err(bad());
 71	    }
 72	    (0..text.len())
 73	        .step_by(2)
 74	        .map(|i| {
 75	            text.get(i..i + 2)
 76	                .and_then(|pair| u8::from_str_radix(pair, 16).ok())
 77	                .ok_or_else(bad)
 78	        })
 79	        .collect()
 80	}
 81	
 82	/// The video TrackEntry, every value checked first.
 83	fn video_entry(v: &VideoLayout) -> Result<Vec<u8>, String> {
 84	    let private = match (v.codec_id.as_str(), &v.codec_private_hex) {
 85	        ("V_AV1", Some(text)) => {
 86	            let private = unhex("codec_private_hex", text)?;
 87	            if private.is_empty() {
 88	                return Err("the V_AV1 codec_private_hex is empty".to_string());
 89	            }
 90	            Some(private)
 91	        }
 92	        ("V_AV1", None) => return Err("the V_AV1 codec_private_hex is empty".to_string()),
 93	        ("V_VP9", None) => None,
 94	        ("V_VP9", Some(_)) => return Err("a V_VP9 track takes no codec_private_hex".to_string()),
 95	        (other, _) => return Err(format!("video codec_id \"{other}\" is not V_AV1 or V_VP9")),
 96	    };
 97	    if v.width == 0 || v.height == 0 {
 98	        return Err(format!(
 99	            "the video size {} × {} has a side of 0",
100	            v.width, v.height
101	        ));
102	    }
103	    let [num, den] = v.fps;
104	    if num == 0 || den == 0 {
105	        return Err(format!("the video fps [{num}, {den}] is not a rate"));
106	    }
107	    let c = &v.colour;
108	    if c.bits_per_channel != 8 && c.bits_per_channel != 10 {
109	        return Err(format!(
110	            "colour bits_per_channel {} is not 8 or 10",
111	            c.bits_per_channel
112	        ));
113	    }
114	    let mastering = match &c.mdcv_hex {
115	        Some(text) => {
116	            let b = unhex("mdcv_hex", text)?;
117	            let m = mastering_from_mdcv(&b);
118	            Some(m.ok_or_else(|| format!("mdcv_hex is {} bytes, not 24", b.len()))?)
119	        }
120	        None => None,
121	    };
122	    let light = match &c.clli_hex {
123	        Some(text) => {
124	            let b = unhex("clli_hex", text)?;
125	            let l = light_from_clli(&b);
126	            Some(l.ok_or_else(|| format!("clli_hex is {} bytes, not 4", b.len()))?)
127	        }
128	        None => None,
129	    };
130	    let colour = ColourOut {
131	        matrix: c.matrix,
132	        range: c.range,
133	        transfer: c.transfer,
134	        primaries: c.primaries,
135	        bits: c.bits_per_channel,
136	        light,
137	        mastering,
138	    };
139	    // round(1e9 · den / num) ns, in integers.
140	    let frame_ns = (1_000_000_000 * u64::from(den) + u64::from(num) / 2) / u64::from(num);
141	    Ok(ebml::video_entry(
142	        &v.codec_id,
143	        private.as_deref(),
144	        v.width,
145	        v.height,
146	        frame_ns,
147	        &colour,
148	    ))
149	}
150	
151	/// The audio TrackEntry, every value checked first.
152	fn audio_entry(a: &AudioLayout) -> Result<Vec<u8>, String> {
153	    if a.codec_id != "A_OPUS" {
154	        return Err(format!("audio codec_id \"{}\" is not A_OPUS", a.codec_id));
155	    }
156	    if a.sample_rate != 48_000 {
157	        return Err(format!("audio sample_rate {} is not 48000", a.sample_rate));
158	    }
159	    if !(1..=2).contains(&a.channels) {
160	        return Err(format!("audio channels {} is not 1 or 2", a.channels));
161	    }
162	    Ok(ebml::audio_entry(a.channels, a.pre_skip))
163	}
164	
165	/// The Chapters element, or `None` for none, every chapter checked first.
166	fn chapters(list: &[ChapterLayout], duration_ns: u64) -> Result<Option<Vec<u8>>, String> {
167	    for (i, c) in list.iter().enumerate() {
168	        let n = i + 1;
169	        if c.end_ns <= c.start_ns {
170	            return Err(format!(
171	                "chapter {n} \"{}\" ends at {} ns, not after its start at {} ns",
172	                c.name, c.end_ns, c.start_ns
173	            ));
174	        }
175	        if c.start_ns >= duration_ns {
176	            return Err(format!(
177	                "chapter {n} \"{}\" starts at {} ns, not before the duration {duration_ns} ns",
178	                c.name, c.start_ns
179	            ));
180	        }
181	    }
182	    let rows: Vec<(u64, u64, &str)> = list
183	        .iter()
184	        .map(|c| (c.start_ns, c.end_ns, c.name.as_str()))
185	        .collect();
186	    Ok((!rows.is_empty()).then(|| ebml::chapters(&rows)))
187	}
188	
189	/// What `open` writes before the first Cluster, every value checked, and
190	/// which tracks the layout declares.
191	pub(crate) struct Header {
192	    pub(crate) info: Vec<u8>,
193	    pub(crate) tracks: Vec<u8>,
194	    pub(crate) chapters: Option<Vec<u8>>,
195	    pub(crate) video: bool,
196	    pub(crate) audio: bool,
197	}
198	
199	impl WebmLayout {
200	    /// Reads and checks the layout `text`, answering its header elements.
201	    pub(crate) fn header(text: &str) -> Result<Header, String> {
202	        let layout: WebmLayout =
203	            serde_json::from_str(text).map_err(|e| format!("the layout could not be read: {e}"))?;
204	        if layout.video.is_none() && layout.audio.is_none() {
205	            return Err("the layout has no video and no audio track".to_string());
206	        }
207	        let mut entries = Vec::new();
208	        if let Some(v) = &layout.video {
209	            entries.push(video_entry(v)?);
210	        }
211	        if let Some(a) = &layout.audio {
212	            entries.push(audio_entry(a)?);
213	        }
214	        Ok(Header {
215	            info: ebml::info(layout.duration_ns),
216	            tracks: ebml::master(ebml::TRACKS, &entries),
217	            chapters: chapters(&layout.chapters, layout.duration_ns)?,
218	            video: layout.video.is_some(),
219	            audio: layout.audio.is_some(),
220	        })
221	    }
222	}

