122	    /// The Lanczos scaler, its transform and clip, and a destination cleared to black once:
123	    /// a fit writes only the picture's rectangle, so the bars stay black on every frame.
124	    private static func scaling(
125	        device: MTLDevice, size: (Int, Int), canvas: CGSize, fills: Bool
