132	            scaleX: s, scaleY: s, translateX: (w - pw) / 2, translateY: (h - ph) / 2)
133	        let descriptor = MTLTextureDescriptor.texture2DDescriptor(
134	            pixelFormat: .rgba16Float, width: size.0, height: size.1, mipmapped: false)
