  2	//  ExportI010.metal — the bundled encoders' frames (spec §11 CX-12 (5),
  3	//  CX-14 (3), CX-16 (3)): a compositor frame (64RGBAHalf, premultiplied, in the
  4	//  encoding of the picture the export writes) converted to video-range 10-bit
  5	//  I010 in three planes of one buffer, each sample 16 bits, little-endian, the
  6	//  10 bits in its low bits (yuv420p10le) — the AV1 rows', and `vp9_webm`'s at
  7	//  HLG and PQ — or, by `framejob_export_i420`, to video-range 8-bit I420, each
  8	//  sample one byte (yuv420p) — `vp9_webm`'s SDR picture. Owned by
  9	//  `app/Sources/ExportI010.swift`, which scales the frame to the export size
 10	//  first when it is not the canvas.
 11	//
 12	//  One thread per 2 × 2 block: it writes the block's four luma samples and
 13	//  one Cb and one Cr, the mean of the four pixels' (a 2 × 2 box, the chroma
 14	//  siting SVT's sequence header leaves unspecified). RGB is clamped to 0…1 and
 15	//  read as it is, premultiplied, so a transparent canvas lands on black as it
 16	//  does through VideoToolbox on `h264`.
 17	//
 18	//  The matrix is the picture's (`kr`, `kb`: BT.709's or BT.2020's):
 19	//  Y′ = kr R + (1 − kr − kb) G + kb B; Cb′ = (B − Y′) / (2 (1 − kb));
 20	//  Cr′ = (R − Y′) / (2 (1 − kr)); Y = round(64 + 876 Y′);
 21	//  C = clamp(round(512 + 896 C′), 0, 1023), C′ the block's mean; at 8 bits
 22	//  Y = round(16 + 219 Y′) and C = clamp(round(128 + 224 C′), 0, 255).
 23	//
 24	
 25	#include <metal_stdlib>
 26	using namespace metal;
 27	
 28	/// Mirrored by `ExportI010Uniforms` in `ExportI010.swift`; every field 32 bits.
 29	/// Strides and offsets are in samples.
 30	struct ExportI010Uniforms {
 31	    uint width;
 32	    uint height;
 33	    uint lumaStride;
 34	    uint chromaStride;
 35	    uint cbOffset;
 36	    uint crOffset;
 37	    float kr;
 38	    float kb;
 39	};
 40	
 41	kernel void framejob_export_i010(texture2d<half, access::read> src [[texture(0)]],
 42	                                 device ushort *planes [[buffer(0)]],
 43	                                 constant ExportI010Uniforms &u [[buffer(1)]],
 44	                                 uint2 gid [[thread_position_in_grid]]) {
 45	    if (gid.x * 2 >= u.width || gid.y * 2 >= u.height) {
 46	        return;
 47	    }
 48	    const float3 weights = float3(u.kr, 1.0 - u.kr - u.kb, u.kb);
 49	    const float cbScale = 2.0 * (1.0 - u.kb);
 50	    const float crScale = 2.0 * (1.0 - u.kr);
 51	    float cb = 0.0;
 52	    float cr = 0.0;
 53	    float count = 0.0;
 54	    for (uint dy = 0; dy < 2; dy++) {
 55	        for (uint dx = 0; dx < 2; dx++) {
 56	            uint2 at = uint2(gid.x * 2 + dx, gid.y * 2 + dy);
 57	            if (at.x >= u.width || at.y >= u.height) {
 58	                continue;
 59	            }
 60	            float3 rgb = clamp(float3(src.read(at).rgb), 0.0, 1.0);
 61	            float luma = dot(rgb, weights);
 62	            planes[at.y * u.lumaStride + at.x] = ushort(round(64.0 + 876.0 * luma));
 63	            cb += (rgb.b - luma) / cbScale;
 64	            cr += (rgb.r - luma) / crScale;
 65	            count += 1.0;
 66	        }
 67	    }
 68	    uint chroma = gid.y * u.chromaStride + gid.x;
 69	    planes[u.cbOffset + chroma] = ushort(clamp(round(512.0 + 896.0 * cb / count), 0.0, 1023.0));
 70	    planes[u.crOffset + chroma] = ushort(clamp(round(512.0 + 896.0 * cr / count), 0.0, 1023.0));
 71	}
 72	
 73	/// The same block at 8 bits (spec §11 CX-16 (3)): one byte a sample, the
 74	/// strides and offsets in samples as above.
 75	kernel void framejob_export_i420(texture2d<half, access::read> src [[texture(0)]],
 76	                                 device uchar *planes [[buffer(0)]],
 77	                                 constant ExportI010Uniforms &u [[buffer(1)]],
 78	                                 uint2 gid [[thread_position_in_grid]]) {
 79	    if (gid.x * 2 >= u.width || gid.y * 2 >= u.height) {
 80	        return;
 81	    }
 82	    const float3 weights = float3(u.kr, 1.0 - u.kr - u.kb, u.kb);
 83	    const float cbScale = 2.0 * (1.0 - u.kb);
 84	    const float crScale = 2.0 * (1.0 - u.kr);
 85	    float cb = 0.0;
 86	    float cr = 0.0;
 87	    float count = 0.0;
 88	    for (uint dy = 0; dy < 2; dy++) {
 89	        for (uint dx = 0; dx < 2; dx++) {
 90	            uint2 at = uint2(gid.x * 2 + dx, gid.y * 2 + dy);
 91	            if (at.x >= u.width || at.y >= u.height) {
 92	                continue;
 93	            }
 94	            float3 rgb = clamp(float3(src.read(at).rgb), 0.0, 1.0);
 95	            float luma = dot(rgb, weights);
 96	            planes[at.y * u.lumaStride + at.x] = uchar(round(16.0 + 219.0 * luma));
 97	            cb += (rgb.b - luma) / cbScale;
 98	            cr += (rgb.r - luma) / crScale;
 99	            count += 1.0;
100	        }
101	    }
102	    uint chroma = gid.y * u.chromaStride + gid.x;
103	    planes[u.cbOffset + chroma] = uchar(clamp(round(128.0 + 224.0 * cb / count), 0.0, 255.0));
104	    planes[u.crOffset + chroma] = uchar(clamp(round(128.0 + 224.0 * cr / count), 0.0, 255.0));
105	}

