     2	
     3	/// Where `ExportEncodePump`'s packets go, once the pump has made them the container's bytes
     4	/// (AV1's temporal delimiters stripped) and put them in order (spec §11 CX-12, CX-15, CX-16):
     5	/// the MP4 row's passthrough `AVAssetWriterInput`, or the WebM rows' core writer. Both are called on the pump's encode
     6	/// queue alone, so a sink needs no lock of its own.
     7	protocol ExportPacketSink: AnyObject {
     8	    /// Writes one packet presented at `time` for `duration`; `key` is a KEY_FRAME. nil once
     9	    /// written; `ExportPacketSinkStopped` when the export stopped first (nothing to report);
    10	    /// any other error fails the export.
    11	    func append(
    12	        _ data: Data, at time: CMTime, duration: CMTime, key: Bool, isStopping: () -> Bool
    13	    ) -> (any Error)?
    14	    /// No packet follows: the pump's one exit calls it exactly once, clean or not.
    15	    func finish()
    16	}
    17	
    18	/// A sink's answer when the export stopped while it waited: the stop is already recorded
    19	/// (a cancel, or another pump's failure), so the pump reports nothing for it.
    20	struct ExportPacketSinkStopped: Error {}
    21	
    22	/// The `av1` row's sink: each packet as one `av01` sample (`ExportAV1Track.sample`) into the
    23	/// passthrough input, after waiting for it to take more; `finish` marks the input finished.
    24	final class ExportMP4PacketSink: ExportPacketSink {
    25	    private let input: AVAssetWriterInput
    26	    /// The `av01` description; nil (never on the `av1` row) makes every packet unwritable.
    27	    private let format: CMVideoFormatDescription?
    28	
    29	    init(input: AVAssetWriterInput, format: CMVideoFormatDescription?) {
    30	        self.input = input
    31	        self.format = format
    32	    }
    33	
    34	    @available(*, unavailable) required init?(coder: NSCoder) {
    35	        fatalError("ExportMP4PacketSink does not support NSCoder")
    36	    }
    37	
    38	    func append(
    39	        _ data: Data, at time: CMTime, duration: CMTime, key: Bool, isStopping: () -> Bool
    40	    ) -> (any Error)? {
    41	        guard let format, let sample = ExportAV1Track.sample(
    42	            data, at: time, duration: duration, format: format)
    43	        else {
    44	            return Exporter.ExportError.failed("An AV1 packet could not be made a sample.")
    45	        }
    46	        while !input.isReadyForMoreMediaData {
    47	            guard !isStopping() else { return ExportPacketSinkStopped() }
    48	            usleep(1000)
    49	        }
    50	        guard input.append(sample) else {
    51	            return Exporter.ExportError.failed("The file could not be written.")
    52	        }
    53	        return nil
    54	    }
    55	
    56	    func finish() {
    57	        input.markAsFinished()
    58	    }
    59	}
    60	
    61	/// The WebM rows' sink: each packet into the core's writer as the video track's block at its
    62	/// time in nanoseconds, the key flag the encoder's (spec §11 CX-15 (3), CX-16 (6)). The core queues
    63	/// what the interleave holds back, so this never waits. `finish` ends the video track; a
    64	/// failure there is the writer's `finish`'s to report.
    65	final class ExportWebMPacketSink: ExportPacketSink {
    66	    private let webm: ReelWebM
    67	    /// `-RCDevWebMFault video@N` (`ExportWebMDevFault`, dev tools only), else nil.
    68	    private let fault: ExportWebMDevFault?
    69	    private var packets = 0
    70	
    71	    init(webm: ReelWebM, fault: ExportWebMDevFault? = nil) {
    72	        self.webm = webm
    73	        self.fault = fault
    74	    }
    75	
    76	    @available(*, unavailable) required init?(coder: NSCoder) {
    77	        fatalError("ExportWebMPacketSink does not support NSCoder")
    78	    }
    79	
    80	    func append(
    81	        _ data: Data, at time: CMTime, duration: CMTime, key: Bool, isStopping: () -> Bool
    82	    ) -> (any Error)? {
    83	        packets += 1
    84	        if let error = fault?.videoPacket(packets) { return error }
    85	        do {
    86	            try webm.add(
    87	                track: ReelWebM.video, ptsNs: Self.nanoseconds(time), key: key,
    88	                discardPaddingNs: 0, data: data)
    89	        } catch {
    90	            return Exporter.ExportError.failed(
    91	                "The WebM file could not be written: \(error.localizedDescription)")
    92	        }
    93	        return nil
    94	    }
    95	
    96	    func finish() {
    97	        try? webm.endTrack(ReelWebM.video)
    98	    }
    99	
   100	    /// `time` in nanoseconds, rounded half away from zero.
   101	    static func nanoseconds(_ time: CMTime) -> Int64 {
   102	        CMTimeConvertScale(time, timescale: 1_000_000_000, method: .roundHalfAwayFromZero).value
   103	    }
   104	}
import AVFoundation

/// `rc_webm_open`'s layout (spec §11 CX-15 (3), CX-16 (4), (5)), the `Encodable` mirror of
/// the core's `WebmLayout`: what an `av1_webm` or `vp9_webm` file is before its first packet.
/// Built from the settings (the size `ExportWriter.encodedSize` gives the encoder, the rate),
/// the pump's video codec (`VideoCodec`: AV1's `av1C` record and sequence-header colour, or
/// VP9's picture CICP and depth with no CodecPrivate), its picture (HD-5's HDR10 blobs on PQ
/// alone), the Opus pre-skip when the composition has sound, and the chapters clamped and
/// rebased by `ExportChapter.partition` — the MP4 writer's own rule.
struct ExportWebMLayout: Encodable {
    /// The video track's codec as `ExportEncodePump` knows it: `V_AV1` with the `av1C` record
    /// as its private and 10 bits, or `V_VP9` with none and 8 or 10 bits (CX-16 (3), (5)); the
    /// CICP the `Colour` carries.
    struct VideoCodec {
        let codecId: String
        let codecPrivate: Data?
        let primaries: Int
        let transfer: Int
        let matrix: Int
        let bitsPerChannel: Int
    }

    struct Video: Encodable {
        let codecId: String
        /// Absent on `V_VP9` (an optional the encoder leaves out).
        let codecPrivateHex: String?
        let width: Int
        let height: Int
        let fps: [Int]
        let colour: Colour
    }

    /// The codec's CICP, video range (Matroska's Range 1), its depth, and on PQ the two blobs
    /// `OutputTransform` writes everywhere else.
    struct Colour: Encodable {
        let matrix: Int
        let range = 1
        let transfer: Int
        let primaries: Int
        let bitsPerChannel: Int
        let mdcvHex: String?
        let clliHex: String?
    }

    struct Audio: Encodable {
        let codecId = "A_OPUS"
        let channels = 2
        let sampleRate = 48_000
        let preSkip: Int
    }

    struct Chapter: Encodable {
        let startNs: Int64
        let endNs: Int64
        let name: String
    }

    let durationNs: Int64
    let video: Video
    /// nil for a composition with no sound: the silent movie (CX-15 (2)).
    let audio: Audio?
    let chapters: [Chapter]

    init(
        settings: ExportSettings, range: CMTimeRange, codec: VideoCodec,
        picture: ExportAV1Picture, preSkip: Int?, chapters: [ExportChapter]
    ) {
        let frame = ExportWriter.encodedSize(settings)
        let hdr10 = picture.carriesHDR10
        durationNs = ExportWebMPacketSink.nanoseconds(range.duration)
        video = Video(
            codecId: codec.codecId, codecPrivateHex: codec.codecPrivate.map(Self.hex),
            width: frame.width, height: frame.height, fps: [settings.fps.num, settings.fps.den],
            colour: Colour(
                matrix: codec.matrix, transfer: codec.transfer, primaries: codec.primaries,
                bitsPerChannel: codec.bitsPerChannel,
                mdcvHex: hdr10 ? Self.hex(OutputTransform.masteringDisplay) : nil,
                clliHex: hdr10 ? Self.hex(OutputTransform.contentLightLevel) : nil))
        audio = preSkip.map { Audio(preSkip: $0) }
        self.chapters = ExportChapter.partition(chapters, in: range).map {
            Chapter(
                startNs: ExportWebMPacketSink.nanoseconds($0.range.start),
                endNs: ExportWebMPacketSink.nanoseconds($0.range.end), name: $0.name)
        }
    }

    /// The layout as the core reads it: snake_case keys, an absent optional left out.
    func json() throws -> String {
        let encoder = JSONEncoder()
        encoder.keyEncodingStrategy = .convertToSnakeCase
        guard let text = String(data: try encoder.encode(self), encoding: .utf8) else {
            throw Exporter.ExportError.failed("The WebM layout could not be written.")
        }
        return text
    }

    private static func hex(_ data: Data) -> String {
        data.map { String(format: "%02x", $0) }.joined()
    }
}

